-- Stage 1: INGEST - unify all raw sources into one table.
-- The union below is generated by run_pipeline.py from data/raw/*_raw.parquet
-- (add a new collector -> new *_raw.parquet -> picked up automatically).
CREATE OR REPLACE TABLE reviews_raw AS
{{RAW_UNION}};

CREATE OR REPLACE TABLE s1_ingest AS
SELECT source, COUNT(*) AS n,
       COUNT(DISTINCT doc_id) AS n_unique,
       AVG(LENGTH(COALESCE(text,''))) AS avg_text_len,
       COUNT(*) FILTER (WHERE rating IS NOT NULL) AS n_with_rating
FROM reviews_raw GROUP BY source ORDER BY n DESC;
